import AppKit
import UniformTypeIdentifiers

public enum ClipboardEvent: Sendable {
    case text(String), oversized, unsupportedText
}

/// Reads only changed pasteboards; pausing/resuming establishes a new changeCount baseline.
@MainActor
public final class PasteboardMonitor {
    public static let excludedTypes: Set<String> = [
        "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType", "de.petermaurer.TransientPasteboardType",
        "PasswordPboardType",
        "com.agilebits.onepassword", "com.agilebits.onepassword.private"
    ]
    private let pasteboard: NSPasteboard
    private let onEvent: (ClipboardEvent) -> Void
    private var timer: Timer?
    private var lastChangeCount: Int
    public private(set) var isPaused = true

    public init(pasteboard: NSPasteboard = .general, onEvent: @escaping (ClipboardEvent) -> Void) {
        self.pasteboard = pasteboard
        self.onEvent = onEvent
        lastChangeCount = pasteboard.changeCount
    }

    public func start(paused: Bool) {
        setPaused(paused)
        guard timer == nil else { return }
        let timer = Timer(timeInterval: 0.75, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        timer.tolerance = 0.2
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    public func stop() { timer?.invalidate(); timer = nil }

    public func setPaused(_ value: Bool) {
        isPaused = value
        lastChangeCount = pasteboard.changeCount
    }

    public func poll() {
        let change = pasteboard.changeCount
        guard change != lastChangeCount else { return }
        lastChangeCount = change
        guard !isPaused else { return }
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.excludedTypes),
              !types.contains(where: { $0.hasPrefix("com.agilebits.onepassword.") }),
              !types.contains("NSFilenamesPboardType"),
              !types.contains(where: { raw in
                  guard let type = UTType(raw) else { return false }
                  return type.conforms(to: .fileURL) || type.conforms(to: .image)
              }) else { return }
        guard let type = [NSPasteboard.PasteboardType.string, .URL].first(where: { types.contains($0.rawValue) }),
              let data = pasteboard.data(forType: type) else { return }
        guard data.count <= HistoryRepository.maximumTextBytes else { onEvent(.oversized); return }
        guard let content = String(data: data, encoding: .utf8), !content.contains("\0") else {
            onEvent(.unsupportedText); return
        }
        guard pasteboard.changeCount == change else { return }
        if !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { onEvent(.text(content)) }
    }

    @discardableResult
    public func copy(_ content: String) -> Bool {
        pasteboard.clearContents()
        let success = pasteboard.setString(content, forType: .string)
        lastChangeCount = pasteboard.changeCount
        return success
    }
}
